// api.ts — typed client built on openapi-fetch. The shape comes from
// api.gen.ts (generated by `npm run gen-api` against ../openapi.json).
//
// Same pattern as weft-webui's lib/api.ts : one createClient call,
// re-exported as `api`, and one helper per operation that hides
// the openapi-fetch envelope so consumers write
// `await listProjects()` instead of
// `await api.GET('/api/projects')` + status check + body destructure.

import createClient from 'openapi-fetch';
import type { paths } from './api.gen';

export const api = createClient<paths>({ baseUrl: '' });

export type Project = NonNullable<
  paths['/api/projects']['get']['responses']['200']['content']['application/json']['items']
>[number];

export type File = NonNullable<
  paths['/api/projects/{name}/files']['get']['responses']['200']['content']['application/json']['items']
>[number];

export async function listProjects(): Promise<Project[]> {
  const { data, error } = await api.GET('/api/projects');
  if (error) throw new Error(`list-projects: ${JSON.stringify(error)}`);
  return data.items ?? [];
}

export async function listFiles(project: string): Promise<File[]> {
  const { data, error } = await api.GET('/api/projects/{name}/files', {
    params: { path: { name: project } },
  });
  if (error) throw new Error(`list-files: ${JSON.stringify(error)}`);
  return data.items ?? [];
}

// Raw read/write/delete bypass the typed huma surface — the openapi
// spec only documents the high-level list. Editor + FileExplorer talk
// to these directly.
export async function writeFile(
  project: string,
  path: string,
  body: string | Uint8Array | Blob,
  contentType: string = 'text/plain',
): Promise<void> {
  const url = `/api/projects/${encodeURIComponent(project)}/files/${path
    .split('/')
    .map(encodeURIComponent)
    .join('/')}`;
  let payload: BodyInit;
  if (typeof body === 'string') payload = body;
  else if (body instanceof Blob) payload = body;
  else payload = new Blob([body as unknown as BlobPart], { type: contentType });
  const resp = await fetch(url, {
    method: 'PUT',
    headers: { 'Content-Type': contentType },
    body: payload,
  });
  if (!resp.ok) {
    throw new Error(`write-file ${resp.status}: ${await resp.text()}`);
  }
}

export async function readFile(
  project: string,
  path: string,
): Promise<string> {
  const url = `/api/projects/${encodeURIComponent(project)}/files/${path
    .split('/')
    .map(encodeURIComponent)
    .join('/')}`;
  const resp = await fetch(url);
  if (!resp.ok) {
    throw new Error(`read-file ${resp.status}: ${await resp.text()}`);
  }
  return resp.text();
}

export async function deleteFile(project: string, path: string): Promise<void> {
  const url = `/api/projects/${encodeURIComponent(project)}/files/${path
    .split('/')
    .map(encodeURIComponent)
    .join('/')}`;
  const resp = await fetch(url, { method: 'DELETE' });
  // Treat 404 as success — the file's already gone (concurrent
  // delete from another tab, e.g.).
  if (!resp.ok && resp.status !== 404) {
    throw new Error(`delete-file ${resp.status}: ${await resp.text()}`);
  }
}

export interface CompileSpec {
  language: string;
  entry?: string;
  extra_args?: string[];
  // command — verbatim shell command that REPLACES the language's
  // default when set. Populated by the SettingsPanel "Compile
  // commands" section. Empty string falls back to the built-in
  // per-language command.
  command?: string;
}

export async function startCompile(
  project: string,
  spec: CompileSpec,
): Promise<string> {
  const { data, error } = await api.POST('/api/projects/{name}/compile', {
    params: { path: { name: project } },
    body: spec,
  });
  if (error) throw new Error(`start-compile: ${JSON.stringify(error)}`);
  return data.id;
}
